// Pedido GET simples com async/await
async function obterUtilizadores() {
  const response = await fetch("https://api.exemplo.com/utilizadores");
  console.log(response); // objeto Response: status, headers, corpo ainda por ler (stream)
  return response;
}

obterUtilizadores();

async function exemploRespostas() {
  const respostaJson = await fetch("https://api.exemplo.com/utilizadores");
  const dados = await respostaJson.json(); // conversão assíncrona para objeto/array JS
  console.log(dados);

  const respostaTexto = await fetch("https://api.exemplo.com/aviso.txt");
  const texto = await respostaTexto.text();
  console.log(texto);

  // Se precisar de ler o mesmo corpo duas vezes, tem de o clonar antes:
  const respostaOriginal = await fetch("https://api.exemplo.com/relatorio");
  const copia = respostaOriginal.clone();
  const comoTexto = await respostaOriginal.text();
  const comoJson = await copia.json().catch(() => null);
  console.log(comoTexto, comoJson);
}

async function obterUtilizador(id) {
  const response = await fetch(`https://api.exemplo.com/utilizadores/${id}`);

  if (!response.ok) {
    // 404, 500, etc. chegam aqui - a Promise NÃO rejeitou sozinha
    throw new Error(`Erro HTTP ${response.status}: ${response.statusText}`);
  }

  return response.json();
}

async function criarUtilizador(dadosUtilizador) {
  const response = await fetch("https://api.exemplo.com/utilizadores", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify(dadosUtilizador),
  });

  const utilizadorCriado = await response.json();
  return utilizadorCriado;
}

criarUtilizador({ nome: "Ana Silva", idade: 28 }).then((utilizador) => {
  console.log(utilizador);
});

async function pesquisarComTimeout(termo, timeoutMs = 5000) {
  const controller = new AbortController();
  const temporizador = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(`https://api.exemplo.com/pesquisa?q=${termo}`, {
      signal: controller.signal,
    });
    return await response.json();
  } catch (erro) {
    if (erro.name === "AbortError") {
      throw new Error("O pedido demorou demasiado tempo e foi cancelado");
    }
    throw erro;
  } finally {
    clearTimeout(temporizador);
  }
}

async function pedidoJSON(url, opcoes) {
  let response;

  try {
    response = await fetch(url, opcoes);
  } catch (erro) {
    // Erro de rede: sem ligação, DNS falhou, CORS bloqueado, etc.
    throw new Error(`Falha de rede ao contactar ${url}: ${erro.message}`);
  }

  if (!response.ok) {
    // Erro HTTP: o servidor respondeu, mas com um estado de erro
    throw new Error(`Erro HTTP ${response.status} ao contactar ${url}`);
  }

  return response.json();
}

async function main() {
  try {
    const dados = await pedidoJSON("https://api.exemplo.com/utilizadores");
    console.log(dados);
  } catch (erro) {
    console.error("Não foi possível obter os dados:", erro.message);
  }
}

main();

