async function obterPost(id) {
  const response = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`);
  const post = await response.json();
  return post;
}

obterPost(1).then((post) => console.log(post.title));

async function obterUtilizadorSeguro(id) {
  const response = await fetch(`https://jsonplaceholder.typicode.com/users/${id}`);

  if (!response.ok) {
    throw new Error(`Utilizador ${id} não encontrado (estado ${response.status})`);
  }

  return response.json();
}

async function testar() {
  try {
    const utilizador = await obterUtilizadorSeguro(9999);
    console.log(utilizador);
  } catch (erro) {
    console.error(erro.message);
  }
}

testar();

async function criarTarefa(titulo, concluida) {
  const response = await fetch("https://jsonplaceholder.typicode.com/todos", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ titulo, concluida }),
  });

  if (!response.ok) {
    throw new Error(`Não foi possível criar a tarefa (estado ${response.status})`);
  }

  return response.json();
}

criarTarefa("Estudar Fetch API", false)
  .then((tarefa) => console.log(tarefa))
  .catch((erro) => console.error(erro.message));

async function obterComTimeout(url, timeoutMs) {
  const controller = new AbortController();
  const temporizador = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(url, { signal: controller.signal });

    if (!response.ok) {
      throw new Error(`Erro HTTP ${response.status} ao contactar ${url}`);
    }

    return await response.json();
  } catch (erro) {
    if (erro.name === "AbortError") {
      throw new Error("Pedido cancelado por exceder o tempo limite");
    }
    throw erro;
  } finally {
    clearTimeout(temporizador);
  }
}
